class Solution:
    def minQuestionMarks(self, patterns: List[str]) -> int:
        m = len(patterns[0])
        cnt = 0
        for j in range(m):
            seen = ''
            for p in patterns:
                ch = p[j]
                if ch == '?':
                    continue
                if not seen:
                    seen = ch
                elif seen != ch:
                    cnt += 1
                    break
        return cnt

