class Solution {
public:
    int minQuestionMarks(vector<string>& patterns) {
        if (patterns.empty()) return 0;
        int m = patterns[0].size(), cnt = 0;
        for (int j = 0; j < m; j++) {
            char seen = 0;
            for (size_t i = 0; i < patterns.size(); i++) {
                char ch = patterns[i][j];
                if (ch == '?') continue;
                if (seen == 0) seen = ch;
                else if (seen != ch) { cnt++; break; }
            }
        }
        return cnt;
    }
};

